import { useState, useEffect, useMemo } from "react";
import axios from "axios";
import { useWishlist } from "../context/WishlistContext";

function HouseCard({ home, openChat }) {
  const [currentImageIndex, setCurrentImageIndex] = useState(0);
  const { wishlist, addToWishlist, removeFromWishlist } = useWishlist();
  const [isInWishlist, setIsInWishlist] = useState(wishlist.includes(home.id));

  const images = useMemo(() => {
    let parsedImages = [];
    if (Array.isArray(home.images)) {
      parsedImages = home.images;
    } else if (typeof home.images === "string") {
      try {
        parsedImages = JSON.parse(home.images) || home.images.split(",");
      } catch (e) {
        console.error("Failed to parse home.images:", e);
        parsedImages = [];
      }
    }
    return parsedImages
      .map((img) => `http://localhost:5000${img}`)
      .filter(Boolean);
  }, [home.images]);

  useEffect(() => {
    if (images.length < 2) return;
    const interval = setInterval(() => {
      setCurrentImageIndex((prev) => (prev + 1) % images.length);
    }, 3000);
    return () => clearInterval(interval);
  }, [images]);

  useEffect(() => {
    const checkWishlist = async () => {
      const userId = localStorage.getItem("userId");
      if (userId) {
        try {
          const response = await axios.get(
            `http://localhost:5000/user/wishlist/${userId}`
          );
          setIsInWishlist(response.data.some((item) => item.id === home.id));
        } catch (err) {
          console.error("Wishlist check failed:", err);
        }
      }
    };
    checkWishlist();
  }, [home.id]);

  const handleBook = async () => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to book a home");
      return;
    }
    try {
      await axios.post(`http://localhost:5000/book/${home.id}`, { userId });
      alert("Home successfully booked");
    } catch (err) {
      alert("Booking failed: " + err.message);
    }
  };

  const handleWishlistToggle = () => {
    const userId = localStorage.getItem("userId");
    if (!userId) {
      alert("Please log in to add to wishlist");
      return;
    }
    if (isInWishlist) {
      removeFromWishlist(home.id);
      axios.delete(`http://localhost:5000/wishlist/remove`, {
        data: { userId, houseId: home.id },
      });
    } else {
      addToWishlist(home.id);
      axios.post(`http://localhost:5000/wishlist/add`, {
        userId,
        houseId: home.id,
      });
    }
    setIsInWishlist(!isInWishlist);
  };

  return (
    <div className="bg-black bg-opacity-60 rounded-2xl shadow-lg overflow-hidden flex flex-col h-full hover:-translate-y-1 transition-transform">
      {images.length > 0 ? (
        <div className="relative w-full h-48 md:h-64">
          {images.map((img, i) => (
            <img
              key={i}
              src={img}
              alt={`House ${i + 1}`}
              className={`absolute inset-0 w-full h-full object-cover transition-opacity duration-500 ${
                i === currentImageIndex ? "opacity-100" : "opacity-0"
              }`}
            />
          ))}
        </div>
      ) : (
        <div className="w-full h-48 md:h-64 bg-gray-200 flex items-center justify-center">
          <span className="text-gray-500">No Image Available</span>
        </div>
      )}

      <div className="p-6 flex flex-col flex-1 justify-between">
        <div>
          <h3 className="text-2xl font-semibold">{home.address}</h3>
          <p className="text-lg opacity-90">
            <strong>Owner:</strong> {home.owner_name}
          </p>
          <p className="text-lg opacity-90">
            <strong>Contact:</strong> {home.contact}
          </p>
          <p className="text-lg opacity-90">
            <strong>Price:</strong> ₹{home.price}
          </p>
        </div>

        <div className="flex justify-between mt-4 gap-2">
          <button
            onClick={handleWishlistToggle}
            className="flex-1 py-2 bg-red-500 text-white rounded-full hover:bg-red-700 flex items-center justify-center gap-2"
          >
            <img
              src={
                isInWishlist
                  ? "http://localhost:5000/heart_filled.jpg"
                  : "http://localhost:5000/heart_raw.jpg"
              }
              alt="wishlist"
              className="w-5 h-5"
            />
            {isInWishlist ? "Remove from Wishlist" : "Add to Wishlist"}
          </button>

          <button
            onClick={handleBook}
            className="flex-1 py-2 bg-blue-500 text-white rounded-full hover:bg-blue-700 flex items-center justify-center gap-2"
          >
            <img
              src="http://localhost:5000/heart_raw.jpg" // Replace with a book icon if available
              alt="book"
              className="w-5 h-5"
            />
            Book
          </button>

          <a
            href={`https://www.google.com/maps?q=${home.latitude},${home.longitude}`}
            target="_blank"
            rel="noopener noreferrer"
            className="flex-1 py-2 bg-green-500 text-white rounded-full hover:bg-green-700 flex items-center justify-center gap-2"
          >
            <img
              src="http://localhost:5000/location_icon.jpg"
              alt="map"
              className="w-5 h-5"
            />
            Map
          </a>

          <button
            onClick={() => openChat(home.id, home.owner_name)}
            className="flex-1 py-2 bg-yellow-500 text-black rounded-full hover:bg-yellow-600 flex items-center justify-center gap-2"
          >
            💬 Chat
          </button>
        </div>
      </div>
    </div>
  );
}

export default HouseCard;
